INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-01','Per-Unit System: Base Values','Easy','EEE','arena','calculate','Power Systems','multiple_choice','A power system has base values: S_base = 100 MVA, V_base = 11 kV. What is the base impedance?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-02','Overhead Transmission Line: ABCD Parameters','Easy','EEE','arena','interpret','Power Systems','multiple_choice','For a short transmission line (< 80 km), the shunt capacitance is neglected. The ABCD parameters simplify to:','{"choices": ["A=0, B=Z, C=1, D=0", "A=1, B=Z, C=0, D=1 (where Z = R + jωL is the series impedance)", "A=Z, B=1, C=0, D=Z", "A=1, B=0, C=Y, D=1"], "correct": 1}'::jsonb,'Short line equivalent: series impedance Z only. Matrix: [A,B;C,D] = [1,Z;0,1]. A=D=1, B=Z, C=0. Medium line (80–250 km): nominal π model adds shunt admittance. Long line (>250 km): distributed parameter model with hyperbolic functions.','{multiple_choice}'::text[],0.80) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-03','Ferranti Effect','Easy','EEE','arena','predict','Power Systems','multiple_choice','The Ferranti effect in a lightly loaded or no-load transmission line causes:','{"choices": ["Voltage to drop along the line", "Receiving end voltage to be higher than sending end voltage — due to charging current of the line capacitance flowing through the line inductance, causing a voltage rise", "Current to be zero everywhere", "Frequency to increase at the receiving end"], "correct": 1}'::jsonb,'Ferranti effect: capacitive charging current (leading) × line inductance → voltage rise. V_R > V_S. Can cause overvoltage stress on transformers and insulation at no-load. Mitigated by shunt reactors at the receiving end to absorb reactive power.','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-04','Load Flow Analysis: Newton-Raphson','Easy','EEE','arena','select','Power Systems','multiple_choice','Newton-Raphson method is preferred over Gauss-Seidel for large power system load flow because:','{"choices": ["Gauss-Seidel always diverges for large systems", "Newton-Raphson has quadratic convergence — doubles significant figures each iteration; 4–5 iterations for full network solution; superior for large, heavily loaded, or poorly conditioned systems", "Newton-Raphson uses less memory", "Gauss-Seidel has numerical instability"], "correct": 1}'::jsonb,'Gauss-Seidel: linear convergence (one decimal place per iteration), simple implementation. Newton-Raphson: forms and solves Jacobian matrix (NxN) each iteration → quadratic convergence → fewer iterations for large systems. Fast Decoupled Load Flow: simplified Jacobian → faster, slight accuracy compromise.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-05','Symmetrical Components: Positive Sequence','Easy','EEE','arena','interpret','Power Systems','multiple_choice','In symmetrical components analysis, positive sequence components (a-b-c order) are used to analyse:','{"choices": ["Only fault conditions", "Balanced three-phase conditions (normal operation) — positive sequence is the normal abc rotation; negative sequence arises from imbalance; zero sequence from ground currents", "Only single-phase systems", "Phase angle between voltage and current only"], "correct": 1}'::jsonb,'Symmetrical components (Fortescue): any unbalanced 3-phase set = positive + negative + zero sequences. Positive: balanced abc (normal). Negative: balanced acb (reverse rotation — caused by unbalanced load, asymmetric fault). Zero: all same phase (3I₀ flows in ground).','{multiple_choice}'::text[],0.80) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-06','Circuit Breaker: Arc Interruption','Medium','EEE','arena','interpret','Power Systems','multiple_choice','A high-voltage circuit breaker interrupts fault current at:','{"choices": ["Peak of the fault current", "Natural current zero — the arc that forms between opening contacts extinguishes at the natural zero crossing of AC current; breaker must then withstand the transient recovery voltage (TRV) without re-striking", "Any point determined by the relay", "After a fixed 100 ms delay"], "correct": 1}'::jsonb,'AC interruption: arc forms when contacts separate, plasma conducts current. At natural zero crossing, current = 0 and arc can extinguish. The insulating medium (SF₆, vacuum, oil, air) prevents re-ignition as TRV appears across the open contacts. DC circuits: harder (no natural zero).','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-07','Distance Protection: Zone Settings','Medium','EEE','arena','interpret','Power Systems','multiple_choice','A distance relay Zone 1 is typically set to cover 80% of the protected line length (not 100%) because:','{"choices": ["To save relay cost", "Measurement errors, CT/VT inaccuracies, and mutual coupling — setting to 80% provides margin so that the relay never trips for faults beyond the protected line''s remote bus (no overreach)", "Zone 1 reaches the remote substation only", "Zone 2 covers the remaining 20%"], "correct": 1}'::jsonb,'Zone 1 (instantaneous): 80-85% of line. Zone 2 (delayed, ~0.3 s): 100% of line + 20% of next line. Zone 3 (delayed, ~0.6 s): backup for adjacent zone. The 80% setting prevents overreach due to: arc resistance, CT saturation, power swings, mutual coupling from parallel circuits.','{multiple_choice}'::text[],0.70) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-08','Economic Dispatch: Lambda Iteration','Medium','EEE','arena','interpret','Power Systems','multiple_choice','In economic dispatch of generators, the optimal solution (minimum total fuel cost) requires that:','{"choices": ["All generators operate at maximum output", "Incremental costs (dC/dP) of all dispatched generators are equal (λ = dC₁/dP₁ = dC₂/dP₂ = ...) — this is the equal incremental cost criterion", "Generators with lowest capacity operate at maximum", "Generator with lowest total cost supplies all load"], "correct": 1}'::jsonb,'Economic dispatch: minimise Σ C_i(P_i) subject to Σ P_i = P_load. Using Lagrangian: ∂C_i/∂P_i = λ (common incremental cost). Lambda iteration: start with λ, compute P_i from each generator''s dC/dP = λ, check power balance, adjust λ. Transmission losses handled by penalty factors.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-09','Reactive Power: Voltage Control','Medium','EEE','arena','interpret','Power Systems','multiple_choice','In a power system, reactive power (Q) primarily affects:','{"choices": ["System frequency", "Real power (MW) generation", "Bus voltages — injecting reactive power (leading, capacitive) raises voltage; absorbing reactive power (lagging, inductive) lowers voltage", "Active power losses only"], "correct": 2}'::jsonb,'P-f coupling: real power controls frequency. Q-V coupling: reactive power controls voltage. Voltage control sources: AVR on generators, capacitor banks, SVCs, STATCOMs, tap-changing transformers. Reactive power does not travel efficiently over long lines (Q losses in X).','{multiple_choice}'::text[],0.74) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-10','Transformer: On-Load Tap Changer (OLTC)','Medium','EEE','arena','interpret','Power Systems','multiple_choice','An OLTC (On-Load Tap Changer) transformer maintains secondary voltage by:','{"choices": ["Changing the transformer''s core cross-section", "Switching between taps on the transformer winding while carrying load current — changes turns ratio (±10–15% in steps of 1.25% typically) without interrupting supply", "Disconnecting the transformer from the grid", "Adjusting the transformer cooling system"], "correct": 1}'::jsonb,'OLTC: motor-operated tap selector switches between ±n tap positions (typically ±8 steps of 1.25% each). Changeover under load requires transition impedance or moving-contact diverter switch to avoid arcing. Critical for HV/MV substation voltage regulation throughout the day.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-11','HVDC vs HVAC Transmission','Medium','EEE','arena','compare','Power Systems','multiple_choice','HVDC (High Voltage Direct Current) transmission is preferred over HVAC for:','{"choices": ["Short distances below 100 km", "Connecting two AC systems operating at different frequencies or asynchronously, undersea cables >50 km (no charging current issues), and distances >600 km (lower losses than AC with skin effect and reactive power)", "Distribution within cities", "Connecting residential loads"], "correct": 1}'::jsonb,'HVDC advantages: no skin effect, no reactive power charging in cables (DC capacitance not an issue), asynchronous interconnection (no stability constraints between systems), controllable power flow. Break-even vs HVAC: ~600 km overhead, ~50 km cable (due to converter station cost).','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-12','Power System Stability: Swing Equation','Hard','EEE','arena','interpret','Power Systems','multiple_choice','The swing equation of a synchronous machine is: (2H/ωs) × d²δ/dt² = P_m − P_e. The inertia constant H affects stability because:','{"choices": ["Higher H means faster rotor acceleration for the same unbalance", "Higher H means slower rate of change of rotor angle (δ) for a given power imbalance — more kinetic energy → more time before loss of synchronism → easier to maintain stability", "H has no effect on transient stability", "Higher H always prevents all faults from causing instability"], "correct": 1}'::jsonb,'H = stored kinetic energy at rated speed / rated MVA. Higher H → larger denominator in d²δ/dt² → smaller angular acceleration for same P_m−P_e imbalance → more time for controls to respond. Critical clearing time increases with H. Wind/solar (no inertia) reduces grid H → faster frequency changes.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-13','Short Circuit Analysis: MVA Method','Hard','EEE','arena','calculate','Power Systems','multiple_choice','Bus A has available fault MVA = 2000 MVA. A feeder with impedance 0.05 pu (on 100 MVA base) is connected. Fault MVA at the end of the feeder:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-14','Differential Protection: Biased Characteristic','Hard','EEE','arena','interpret','Power Systems','multiple_choice','A biased (percentage) differential relay for a power transformer uses a restraint current to avoid false tripping during:','{"choices": ["Internal faults — when the relay should trip", "External faults and inrush — high through-fault current causes CT saturation mismatch; the biased characteristic requires larger differential current for larger restraint current, preventing maloperation", "Normal load conditions only", "Single-phase operation"], "correct": 1}'::jsonb,'Unbiased differential: trips when I_diff > threshold. Problem: heavy external fault → CT saturation → apparent differential current → false trip. Biased: trip threshold = k × I_restraint + I_min. As through-fault current increases, threshold rises → inherently stable for external faults and CT mismatch.','{multiple_choice}'::text[],0.60) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-15','Voltage Stability: P-V Curve','Hard','EEE','arena','interpret','Power Systems','multiple_choice','On a P-V (nose) curve for a bus, the operating point on the lower portion of the curve is:','{"choices": ["Normal operating region with good voltage regulation", "An unstable equilibrium — small increase in load causes voltage to collapse; the system cannot regulate voltage", "Maximum power transfer point", "The Ferranti effect region"], "correct": 1}'::jsonb,'P-V curve: upper portion = stable, normal operation (voltage decreases gradually with load). Nose point = voltage collapse boundary (maximum loadability). Lower portion = unstable — voltage drops rapidly with load; any disturbance causes collapse. Operating here is dangerous and violates reliability standards.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-16','Auto-Recloser in Distribution','Hard','EEE','arena','select','Power Systems','multiple_choice','Auto-reclosers are used on overhead distribution feeders because:','{"choices": ["They are cheaper than circuit breakers", "About 80% of distribution faults are transient (lightning, bird contact, tree branch) — auto-reclose after 0.3–1 s allows the fault to clear and service to restore automatically without a crew dispatch", "They provide faster fault detection than relays", "They eliminate transformer damage from faults"], "correct": 1}'::jsonb,'Recloser sequence: fault detected → open → wait (0.3 s) → close → if fault cleared → normal operation. If fault persists → open again → wait longer → close again. Typically 3 shots before lockout (for permanent faults). 80% success rate eliminates sustained outages for transient faults.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-17','Wide-Area Monitoring: PMU','Hard','EEE','arena','interpret','Power Systems','multiple_choice','Phasor Measurement Units (PMUs) are superior to conventional SCADA measurements for dynamic stability monitoring because:','{"choices": ["PMUs measure RMS values more accurately", "PMUs provide GPS-synchronised time-stamped phasor measurements at 30–120 samples/s vs SCADA at 1/15 s — enabling real-time observation of inter-area oscillations (0.1–2 Hz), transient stability, and sub-synchronous resonance", "PMUs measure DC currents", "PMUs eliminate need for current transformers"], "correct": 1}'::jsonb,'SCADA/EMS: 2–4 second scan cycle (too slow for dynamics). PMU: 50 Hz sampling (IEEE C37.118), GPS-synchronised to <1 µs across the entire grid → accurate phasor comparison between distant buses → dynamic state estimation, oscillation monitoring, model validation.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-18','Power System Harmonics: IEEE 519','Hard','EEE','arena','interpret','Power Systems','multiple_choice','IEEE 519 limits current harmonics injected by non-linear loads because:','{"choices": ["To reduce system frequency", "Harmonics cause: additional transformer/motor heating (skin effect, hysteresis), neutral conductor overloading (zero-sequence triplen harmonics sum in neutral), metering errors, telephone interference, capacitor bank resonance", "To increase power factor", "To improve relay sensitivity"], "correct": 1}'::jsonb,'Harmonic sources: VFDs, switch-mode PSUs, arc furnaces, UPS. Effects: 3rd harmonic (180 Hz) triplen currents add in neutral (3×I₃ in neutral for balanced 3-phase). Motor/transformer heating increases with harmonic order. Capacitor bank resonance at harmonic frequency can cause overcurrent. IEEE 519: limits THD at PCC.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-19','SCADA in Power Systems','Hard','EEE','arena','select','Power Systems','multiple_choice','SCADA (Supervisory Control and Data Acquisition) in power systems is vulnerable to cybersecurity attacks because:','{"choices": ["SCADA uses encrypted communications only", "Legacy SCADA systems often use serial/MODBUS protocols with no authentication, are connected to corporate IT networks, use proprietary software with unpatched vulnerabilities — creating attack surface for ICS-specific malware (Stuxnet, Industroyer)", "SCADA systems are air-gapped from all networks", "SCADA only handles metering data, not control"], "correct": 1}'::jsonb,'Ukraine 2015 blackout: Industroyer/CRASHOVERRIDE malware triggered circuit breakers via compromised SCADA. NERC CIP (North American Electric Reliability Corporation Critical Infrastructure Protection) standards mandate cybersecurity controls. IEC 62351 defines security for power system protocols.','{multiple_choice}'::text[],0.60) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-20','Optimal Power Flow (OPF)','Hard','EEE','arena','interpret','Power Systems','multiple_choice','Optimal Power Flow (OPF) differs from Economic Dispatch in that:','{"choices": ["OPF only minimises fuel cost", "OPF optimises the objective function (cost, losses, or emissions) subject to physical network constraints — including line flow limits, voltage limits, and reactive power limits — while economic dispatch ignores network constraints", "OPF is a simpler computation", "Economic dispatch includes more constraints than OPF"], "correct": 1}'::jsonb,'Economic dispatch: ignores network (only power balance). OPF: includes network model → includes thermal line limits, voltage profile constraints, reactive power balance. Security-constrained OPF (SCOPF) additionally ensures N-1 contingency security. AC-OPF is non-convex; DC-OPF linearises for tractability.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-21','Transient Stability: Equal Area Criterion','Hard','EEE','arena','interpret','Power Systems','multiple_choice','The Equal Area Criterion for transient stability states that a system remains stable after a fault if:','{"choices": ["The fault is cleared in less than 0.1 s", "The decelerating area (A₂: area available for deceleration after fault clearing) ≥ the accelerating area (A₁: area swept during fault) — graphically, the rotor can swing back to equilibrium", "The pre-fault power exceeds post-fault power", "Generator inertia is above a minimum value"], "correct": 1}'::jsonb,'Equal area criterion: used for two-machine or single-machine-infinite-bus (SMIB) systems. A₁ = ∫(P_m − P_e_fault)dδ during fault. A₂ = ∫(P_e_post − P_m)dδ after clearing. If A₂ < A₁: rotor cannot decelerate → δ increases without bound → instability. Critical clearing angle where A₂ = A₁.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-22','Gas Insulated Switchgear (GIS)','Hard','EEE','arena','compare','Power Systems','multiple_choice','GIS (Gas Insulated Switchgear) is preferred over air-insulated switchgear (AIS) for urban substation applications because:','{"choices": ["GIS is cheaper to install", "GIS uses SF₆ gas for insulation — dielectric strength 3× air — enabling 10× smaller equipment footprint; essential in dense urban areas where land cost prohibits large outdoor substations", "GIS provides better visual inspection access", "GIS eliminates need for circuit breakers"], "correct": 1}'::jsonb,'GIS: SF₆ at 4–6 bar absolute pressure. All live parts enclosed in grounded aluminium enclosures → weather-independent, low maintenance, small footprint. Disadvantage: SF₆ is a potent greenhouse gas (GWP 23,500 × CO₂). New GIS designs moving to g³ (Green Gas for Grid) mixtures.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-23','Virtual Power Plant (VPP)','Hard','EEE','arena','interpret','Power Systems','multiple_choice','A Virtual Power Plant (VPP) aggregates distributed energy resources (DERs) to participate in electricity markets as a single entity because:','{"choices": ["Individual DERs are too large to control independently", "Small DERs (solar, battery, EV, demand response) individually fall below market participation thresholds; VPP aggregates them to meet minimum bid size, optimises portfolio dispatch, and provides grid services (frequency response, peak shaving)", "VPPs eliminate the need for the main grid", "VPPs only work with large wind turbines"], "correct": 1}'::jsonb,'VPP: software platform aggregates: rooftop solar (100–10 kW), home batteries, EV chargers, HVACs into a coordinated dispatchable resource. Can bid frequency regulation, peak demand reduction into wholesale market. SA Tesla big battery VPP: 50,000 homes, 250 MW dispatchable capacity.','{multiple_choice}'::text[],0.60) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-24','Grounding: Solidly Grounded vs Resistance Grounded','Hard','EEE','arena','compare','Power Systems','multiple_choice','High-resistance grounding (HRG) in industrial power systems allows:','{"choices": ["Higher fault current for faster relay operation", "Continued operation during a single line-to-ground fault without tripping — the high-resistance limits fault current to < 5 A (below damage threshold), allowing production to continue while the fault is located", "Zero sequence protection to be disabled", "Higher insulation voltage rating"], "correct": 1}'::jsonb,'HRG: neutral grounded through R = V_LN / I_fault_max (typically 1–5 A). Single LG fault: system remains operable, alarm generated, fault located with pulse current techniques. Advantage: no unplanned production shutdown. Disadvantage: if second fault occurs on another phase → line-to-line fault → larger fault current.','{multiple_choice}'::text[],0.60) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-ps-25','Electricity Market: Locational Marginal Price','Hard','EEE','arena','interpret','Power Systems','multiple_choice','Locational Marginal Price (LMP) in deregulated electricity markets differs from a single zonal price because:','{"choices": ["LMP is always lower than zonal price", "LMP reflects the marginal cost of serving one additional MW of load at each bus — including energy cost, transmission congestion cost, and marginal loss component; congested lines create price differences between buses", "LMP ignores transmission limits", "LMP is only used for reactive power pricing"], "correct": 1}'::jsonb,'LMP = Energy price + Congestion price + Loss price. When line is congested: load pockets have higher LMP (expensive local generation must run). Generators near load: low congestion component → competitive. Generators far from load: high congestion component in LMP. Used in PJM, NYISO, ERCOT markets.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
